23	export function adjacentConflicts(row: readonly Container[]): Array<[string, string]> {
24	  const out: Array<[string, string]> = [];
25	  for (let i = 1; i < row.length; i++) {
26	    const a = row[i - 1];
27	    const b = row[i];
28	    if (a.dgClass && b.dgClass && mustSegregate(a.dgClass, b.dgClass)) {
29	      out.push([a.id, b.id]);
30	    }
31	  }
32	  return out;
