export function mustSegregate(a: string, b: string): boolean {
  const left = SEGREGATION[a] ?? SEGREGATION[primaryClass(a)] ?? [];
  const right = SEGREGATION[b] ?? SEGREGATION[primaryClass(b)] ?? [];
  return left.includes(b) || left.includes(primaryClass(b)) || right.includes(a) || right.includes(primaryClass(a));
}

